<?php declare(strict_types=1);require __DIR__.'/_common.php';$pdo=db();$lang=(($_GET['lang']??'en')==='fr')?'fr':'en';$error='';$done=false;$token=clean_text($_GET['token']??'',200);$stmt=$pdo->prepare("SELECT * FROM survey_v2_guardian_consents WHERE confirm_token_hash=? LIMIT 1");$stmt->execute([token_hash($token)]);$row=$stmt->fetch();if(!$row){$error=$lang==='fr'?'Ce lien est invalide ou expiré.':'This permission link is invalid or expired.';}elseif($row['status']==='confirmed'){$done=true;}elseif($row['status']!=='pending'){$error=$lang==='fr'?'Cette demande n’est plus active.':'This permission request is no longer active.';}elseif(strtotime((string)$row['expires_at'])<time()){$pdo->prepare("UPDATE survey_v2_guardian_consents SET status='expired',email_encrypted=NULL,updated_at=NOW() WHERE id=?")->execute([$row['id']]);$error=$lang==='fr'?'Cette demande a expiré.':'This permission request expired.';}elseif($_SERVER['REQUEST_METHOD']==='POST'){if(($_POST['guardian_confirm']??'')!=='yes'){$error=$lang==='fr'?'Merci de confirmer la déclaration.':'Please confirm the permission statement.';}else{$revokeToken=random_token();$pdo->prepare("UPDATE survey_v2_guardian_consents SET status='confirmed',confirmed_at=NOW(),updated_at=NOW(),revoke_token_hash=? WHERE id=?")->execute([token_hash($revokeToken),$row['id']]);$done=true;$revokeUrl=v2_base_url('guardian-revoke.php?lang='.$lang.'&token='.rawurlencode($revokeToken));$email=decrypt_string($row['email_encrypted']);if($email){if($lang==='fr'){$title='Autorisation confirmée — recherche produit';$body='<p>Votre autorisation est enregistrée. Le jeune reste libre de continuer ou d’arrêter.</p>'.button_html('Retirer l’autorisation / supprimer la réponse liée',$revokeUrl);$plain="Autorisation confirmée.\n\nRetirer :\n{$revokeUrl}\n";}else{$title='Permission confirmed — product research';$body='<p>Your permission has been recorded. The young participant still chooses whether to continue or stop.</p>'.button_html('Withdraw permission / delete linked response',$revokeUrl);$plain="Permission confirmed.\n\nWithdraw:\n{$revokeUrl}\n";}try{send_app_email($email,$title,email_layout($title,$body),$plain);}catch(Throwable $e){error_log('[V2 guardian confirmation mail] '.$e->getMessage());}}}}?><!doctype html><html lang="<?=v2_h($lang)?>"><head>
