<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Permission</title><style>:root{--bg:#f5f3ed;--card:#fffdfa;--text:#203028;--muted:#65736b;--line:#d9dfd8;--green:#4f7a61;--green2:#dfece3;--peach:#f3e4dc;--shadow:0 14px 40px rgba(33,48,40,.08)}*{box-sizing:border-box}html{background:var(--bg);color:var(--text);font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif}body{margin:0;padding:18px}a{color:#315f45}.shell{max-width:900px;margin:0 auto}.header{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:14px}.brand{text-decoration:none;color:var(--text);font-weight:850}.lang{display:flex;gap:6px}.lang button,.lang a{padding:7px 10px;border-radius:999px}.lang .active{background:var(--green);color:#fff;border-color:var(--green)}.card{background:var(--card);border:1px solid var(--line);border-radius:26px;padding:clamp(20px,4vw,36px);box-shadow:var(--shadow)}.eyebrow{text-transform:uppercase;letter-spacing:.08em;font-size:.76rem;font-weight:850;color:var(--green)}h1,h2,h3{line-height:1.12;margin-top:.2em}h1{font-size:clamp(2rem,6vw,3.5rem)}h2{font-size:clamp(1.55rem,4vw,2.4rem)}.lead{font-size:1.05rem;line-height:1.55;color:#45564d}.small{font-size:.86rem;color:var(--muted);line-height:1.45}.notice,.soft{border:1px solid var(--line);border-radius:18px;padding:15px 16px;margin:16px 0;background:#fafaf7;line-height:1.5}.soft{background:var(--green2)}.actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:22px}button,.btn{appearance:none;border:1px solid transparent;border-radius:15px;padding:13px 17px;font:inherit;font-weight:800;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;justify-content:center}.primary{background:var(--green);color:white}.secondary{background:white;color:var(--text);border-color:var(--line)}.quiet{background:transparent;color:var(--green)}button:disabled{opacity:.55;cursor:not-allowed}.options{display:grid;gap:10px;margin:18px 0}.option{display:flex;gap:12px;align-items:flex-start;border:1px solid var(--line);border-radius:17px;padding:14px;background:white;cursor:pointer}.option:has(input:checked){outline:3px solid rgba(79,122,97,.18);border-color:var(--green);background:#f7fbf8}.option input{margin-top:3px;accent-color:var(--green)}.progress{height:8px;border-radius:999px;background:#e7ebe6;overflow:hidden;margin:8px 0 20px}.progress>span{display:block;height:100%;background:var(--green)}.visuals{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:18px 0}.vcard{border:1px solid var(--line);border-radius:19px;padding:14px;background:#fff;cursor:pointer;display:block}.vcard:has(input:checked){outline:3px solid rgba(79,122,97,.18);border-color:var(--green)}.vcard input{accent-color:var(--green)}.mock{white-space:pre-line;background:#f4f5f1;border:1px solid #e1e5df;border-radius:13px;padding:12px;margin:10px 0;font-size:.84rem;line-height:1.45;min-height:104px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.module{border:1px solid var(--line);border-radius:19px;padding:17px;background:white;display:flex;flex-direction:column;justify-content:space-between;gap:12px}.module.done{background:var(--green2)}.badge{display:inline-flex;width:max-content;padding:5px 8px;border-radius:999px;background:#eef2ed;color:var(--muted);font-size:.75rem;font-weight:800}.consent{display:flex;gap:10px;align-items:flex-start;margin:12px 0;line-height:1.45}.consent input{margin-top:4px;accent-color:var(--green)}.field{width:100%;border:1px solid var(--line);border-radius:14px;padding:13px;font:inherit;background:white}.error{background:#f7e5e5;border-color:#e4c6c6;color:#6e3030}.footer{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:18px 4px;color:var(--muted);font-size:.82rem}.tablewrap{overflow:auto;border:1px solid var(--line);border-radius:16px}table{width:100%;border-collapse:collapse;min-width:640px}th,td{padding:10px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}@media(max-width:680px){body{padding:10px}.grid,.visuals{grid-template-columns:1fr}.actions>*{flex:1 1 100%}.card{border-radius:20px}.header{align-items:flex-start;flex-direction:column}}</style></head><body><div class="shell"><main class="card"><?php if($done):?><h1><?= $lang==='fr'?'Autorisation confirmée':'Permission confirmed' ?></h1><p class="lead"><?= $lang==='fr'?'Le jeune peut maintenant revenir sur son appareil et vérifier l’autorisation. Il reste libre d’arrêter à tout moment.':'The young participant can now return to their device and check permission. They can still stop at any time.' ?></p><?php elseif($error):?><h1><?= $lang==='fr'?'Impossible de confirmer':'Could not confirm permission' ?></h1><div class="notice error"><?=v2_h($error)?></div><?php else:?><h1><?= $lang==='fr'?'Examiner la demande':'Review the request' ?></h1><p class="lead"><?= $lang==='fr'?'Une personne de 13 à 17 ans souhaite répondre à un questionnaire de conception d’une app d’aide au quotidien.':'A young person aged 13–17 wants to answer a product-design questionnaire about a daily-support app.' ?></p><div class="soft"><?= $lang==='fr'?'<strong>Pas de données médicales demandées.</strong><br>Pas de diagnostic, traitement, âge exact, nom, établissement scolaire, lieu de travail ou e-mail du jeune.':'<strong>No medical data requested.</strong><br>No diagnosis, medication, exact age, name, school, workplace or young participant email.' ?></div><form method="post"><label class="consent"><input type="checkbox" name="guardian_confirm" value="yes"><span><?= $lang==='fr'?'J’ai l’autorité parentale / légale nécessaire et j’autorise cette participation dans ces conditions.':'I have parental/legal authority for this young person and give permission under these conditions.' ?></span></label><div class="actions"><button class="primary" type="submit"><?= $lang==='fr'?'Autoriser':'Give permission' ?></button></div></form><?php endif;?></main></div></body></html>